INSERT INTO ps_category(name, description) VALUES ('Fish', 'Any of numerous cold-blooded aquatic vertebrates characteristically having fins, gills, and a streamlined body');
INSERT INTO ps_category(name, description) VALUES ('Dogs', 'A domesticated carnivorous mammal related to the foxes and wolves and raised in a wide variety of breeds');
INSERT INTO ps_category(name, description) VALUES ('Reptiles', 'Any of various cold-blooded, usually egg-laying vertebrates, such as a snake, lizard, crocodile, turtle');
INSERT INTO ps_category(name, description) VALUES ('Cats', ' Small carnivorous mammal domesticated since early times as a catcher of rats and mice and as a pet and existing in several distinctive breeds and varieties');
INSERT INTO ps_category(name, description) VALUES ('Birds', 'Any of the class Aves of warm-blooded, egg-laying, feathered vertebrates with forelimbs modified to form wings');
